def spit_config(self, conf_file, firstwordonly=False):
        """conf_file a file opened for writing."""

        cfg = ConfigParser.RawConfigParser()
        for sec in _CONFIG_SECS:
            cfg.add_section(sec)

        sec = 'channels'
        for i in sorted(self.pack.D):
            cfg.set(sec, str(i),
                    self.pack.name(i, firstwordonly=firstwordonly))

        sec = 'conditions'
        for k in self.sorted_conkeys():
            cfg.set(sec, k, self.conditions[k])

        cfg.write(conf_file)

def subscribe(self):
        """
        return a generator for all subscribe messages
        :return: None
        """
        while self.run_subscribe_generator:
            if len(self._rx_messages) != 0:
                yield self._rx_messages.pop(0)
        return
